#!/usr/bin/env bash
# Generated by the ai-plugin-sdk build. Edit the plugin's own sources instead.

# What a hook reads when it asks for a setting. Nothing here knows a plugin's
# name, its prefix or any of its keys: the build writes plugin-manifest.sh
# beside this file from the plugin's manifest, and paths.sh reads that.
#
# One of the two files a hook can enter through, so the shell is checked here.
#
# One function to a file, in settings/. This names them in the order they need
# each other, and nothing else.

. "${BASH_SOURCE[0]%/*}/shell.sh"
. "${BASH_SOURCE[0]%/*}/settings/paths.sh"
. "${BASH_SOURCE[0]%/*}/settings/plugin_expanded.sh"
. "${BASH_SOURCE[0]%/*}/settings/settings_from_project.sh"
. "${BASH_SOURCE[0]%/*}/settings/project_settings_file.sh"
. "${BASH_SOURCE[0]%/*}/settings/settings_file_value.sh"
. "${BASH_SOURCE[0]%/*}/settings/plugin_setting_holds.sh"
. "${BASH_SOURCE[0]%/*}/settings/setting_value.sh"
. "${BASH_SOURCE[0]%/*}/settings/setting_on.sh"
. "${BASH_SOURCE[0]%/*}/settings/setting_is_set.sh"
